import { h } from './dom.ts';
// Service Worker registration + version info. The SW (dist/sw.js, generated by scripts/make-sw.mjs) precaches the whole app + data.
export interface VersionInfo {
  version: string;
  files: number;
  builtAt: string;
}

let banner: HTMLElement | null = null;

/** Small "new version" banner. The waiting service worker only takes over (and the page reloads) when the user taps it. */
function showUpdateBanner(reg: ServiceWorkerRegistration) {
  if (banner || !reg.waiting) return;
  const refresh = h('button', {
    class: 'update-go',
    type: 'button',
    onclick: () => {
      const waiting = reg.waiting;
      if (!waiting) return location.reload();
      // reload exactly once, and only because of this tap (the first install also fires controllerchange via clients.claim())
      navigator.serviceWorker.addEventListener('controllerchange', () => location.reload(), { once: true });
      refresh.disabled = true;
      refresh.textContent = '更新中…';
      waiting.postMessage({ type: 'SKIP_WAITING' });
    },
  }, '有新版本，点击刷新');
  banner = h('div', { class: 'update-banner', id: 'update-banner', role: 'status' }, refresh, h('button', { class: 'update-later', type: 'button', 'aria-label': '稍后再说', onclick: () => { banner?.remove(); banner = null; } }, '✕'));
  document.body.append(banner);
}

export function registerSW() {
  if (!import.meta.env.PROD || !('serviceWorker' in navigator)) return;
  window.addEventListener('load', () => {
    // Relative URL: resolves against the page, so it works at the root and under a GitHub Pages sub-path.
    navigator.serviceWorker
      .register('./sw.js', { updateViaCache: 'none' })
      .then((reg) => {
        // A new version is only announced when a SW already controls the page (otherwise it is just the first install).
        const announce = () => navigator.serviceWorker.controller && showUpdateBanner(reg);
        if (reg.waiting) announce();
        reg.addEventListener('updatefound', () => {
          const nw = reg.installing;
          nw?.addEventListener('statechange', () => nw.state === 'installed' && announce());
        });
        return reg.update(); // always check for a newer build when the app is opened
      })
      .catch((e) => console.warn('SW registration failed', e));
  });
}

export async function getVersionInfo(): Promise<VersionInfo | null> {
  try {
    const res = await fetch(import.meta.env.BASE_URL + 'version.json', { cache: 'no-cache' });
    return res.ok ? ((await res.json()) as VersionInfo) : null;
  } catch {
    return null;
  }
}

/** 'ready' = a service worker controls this page and its cache for the current version exists. */
export async function offlineStatus(version?: string): Promise<'ready' | 'installing' | 'unsupported'> {
  if (!('serviceWorker' in navigator) || !import.meta.env.PROD) return 'unsupported';
  if (!navigator.serviceWorker.controller) return 'installing';
  if (version && 'caches' in window && !(await caches.has(`english-reader-${version}`))) return 'installing';
  return 'ready';
}
